@* The page owns the snapshot and the transport; the component owns its view. *@
<TmAgentLanes Snapshot="_snapshot"
              Events="_events"
              OnGapDetected="ReloadAsync"
              @bind-SelectedBlockId="_selectedBlockId"
              Title="Release run">
    <DetailTemplate Context="block">
        <h3>@block.Label</h3>
        <p>@block.Status · @block.Start.ToString("t")</p>
    </DetailTemplate>
</TmAgentLanes>

@code {
    private AgentLanesSnapshot _snapshot = new();
    private IReadOnlyList<AgentLaneEvent> _events = [];
    private string? _selectedBlockId;

    private Task ReloadAsync(long missingSequence) => LoadSnapshotAsync(missingSequence);
}

var planner = new AgentRef("Planner", "planner") { ColorIndex = 0 };
var writer = new AgentRef("Writer", "writer") { ColorIndex = 1 };

var snapshot = new AgentLanesSnapshot
{
    Sequence = 42,
    Agents = [planner, writer],
    Blocks =
    [
        new AgentLaneBlock("b1", "planner", startedAt, "Plan the release")
        {
            End = startedAt.AddMinutes(8),
            Status = AgentActivityStatus.Succeeded,
            Kind = AgentLaneBlockKind.Task,
            Marker = AgentLaneBlockMarker.Approval,
        },
        new AgentLaneBlock("b2", "writer", startedAt.AddMinutes(9), "Write the notes")
        {
            Status = AgentActivityStatus.Running,
            Kind = AgentLaneBlockKind.Tool,
        },
    ],
    Handoffs =
    [
        new AgentHandoffLink("writer", startedAt.AddMinutes(9))
        {
            FromBlockId = "b1",
            Label = "Plan ready",
        },
    ],
};
